    address VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Beer (
    name VARCHAR NOT NULL,
    brewer VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Drinker (
    name VARCHAR NOT NULL,
    address VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Frequents (
    drinker VARCHAR NOT NULL,
    bar VARCHAR NOT NULL,
    times_a_week SMALLINT NOT NULL,
    PRIMARY KEY (drinker, bar),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (bar) REFERENCES Bar(name)
);

CREATE TABLE Serves (
    bar VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    price DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (bar, beer),
    FOREIGN KEY (bar) REFERENCES Bar(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

CREATE TABLE Likes (
    drinker VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    PRIMARY KEY (drinker, beer),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

counterexample:
INSERT INTO Bar (name, address) VALUES ('Bar1', '123 Main St'), ('Bar2', '456 Elm St');
INSERT INTO Beer (name, brewer) VALUES ('Amstel', 'Amstel Brewery'), ('Corona', 'Corona Brewery');
INSERT INTO Drinker (name, address) VALUES ('Alice', '789 Oak St'), ('Bob', '101 Pine St');
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Alice', 'Bar1', 3), ('Bob', 'Bar2', 2);
INSERT INTO Serves (bar, beer, price) VALUES ('Bar1', 'Amstel', 3.00), ('Bar1', 'Corona', 2.50), ('Bar2', 'Corona', 3.50);
INSERT INTO Likes (drinker, beer) VALUES ('Alice', 'Amstel');

